class Solution {
public:
    int minDistance(int height, int width, vector<int>& tree, vector<int>& squirrel, vector<vector<int>>& nuts) {
        auto dist = [](const vector<int>& a, const vector<int>& b) {
            return abs(a[0] - b[0]) + abs(a[1] - b[1]);
        };
        int totDist = 0;
        int maxSave = INT_MIN;
        for (const auto& nut : nuts) {
            int dTree = dist(nut, tree);
            int dSq = dist(nut, squirrel);
            totDist += 2 * dTree;
            maxSave = max(maxSave, dTree - dSq);
        }
        return totDist - maxSave;
    }
};

class Solution {
    public int minDistance(int height, int width, int[] tree, int[] squirrel, int[][] nuts) {
        int totDist = 0;
        int maxSave = Integer.MIN_VALUE;
        for (int[] nut : nuts) {
            int dTree = Math.abs(nut[0] - tree[0]) + Math.abs(nut[1] - tree[1]);
            int dSq = Math.abs(nut[0] - squirrel[0]) + Math.abs(nut[1] - squirrel[1]);
            totDist += 2 * dTree;
            maxSave = Math.max(maxSave, dTree - dSq);
        }
        return totDist - maxSave;
    }
}

/**
 * @param {number} height
 * @param {number} width
 * @param {number[]} tree
 * @param {number[]} squirrel
 * @param {number[][]} nuts
 * @return {number}
